import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    private static final Instant NOW = Instant.parse("2026-10-31T10:00:00Z");

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, Clock.fixed(NOW, ZoneOffset.UTC));

    @Test
    void cancelsPlacedOrdersOlderThanThirtyDaysAndReturnsTheCount() {
        save("old-1", "PLACED", NOW.minusSeconds(31L * 24 * 3600));
        save("old-2", "PLACED", NOW.minusSeconds(365L * 24 * 3600));

        assertEquals(2, service.expireStale());

        assertEquals("CANCELLED", orders.get("old-1").status());
        assertEquals("CANCELLED", orders.get("old-2").status());
    }

    @Test
    void leavesOrdersPlacedThirtyDaysAgoOrLessAlone() {
        // Warsaw is UTC+1 after the October switch, so 30 Warsaw days back is 2026-10-01T11:00Z.
        save("exactly-30", "PLACED", Instant.parse("2026-10-01T11:00:00Z"));
        save("recent", "PLACED", NOW.minusSeconds(29L * 24 * 3600));

        assertEquals(0, service.expireStale());

        assertEquals("PLACED", orders.get("exactly-30").status());
        assertEquals("PLACED", orders.get("recent").status());
    }

    @Test
    void leavesOldOrdersThatAreNotPlacedAlone() {
        Instant old = NOW.minusSeconds(60L * 24 * 3600);
        save("confirmed", "CONFIRMED", old);
        save("cancelled", "CANCELLED", old);
        save("returning", "RETURNING", old);

        assertEquals(0, service.expireStale());

        assertEquals("CONFIRMED", orders.get("confirmed").status());
        assertEquals("CANCELLED", orders.get("cancelled").status());
        assertEquals("RETURNING", orders.get("returning").status());
    }

    private void save(String id, String status, Instant placedAt) {
        Order order = new Order(id, "c-1", Money.pln(1000), placedAt);
        order.changeStatus(status);
        orders.save(order);
    }
}
